css:
.actions {
  display: flex;
  gap: 12px;
  padding: 24px;
}

.btn {
  padding: 8px 16px;
  border: 0;
  border-radius: 6px;
  background-color: #f97316;
  color: #ffffff;
  font: inherit;
  font-family: system-ui, sans-serif;
  cursor: pointer;
}

.btn:focus-visible,
.demo-focus {
  outline: 3px solid #2563eb;
  outline-offset: 3px;
}
